/** `g`. */
export class MessagingState {
  inbound = new InboundState()
  receipts = new ReceiptState()
  outbound = new OutboundState()
  ingress = new IngressState()
  swarmPermissions = new SwarmPermissionState()
  mailbox = new MailboxState()
